CREATE TABLE leads (id INTEGER PRIMARY KEY, owner TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, company TEXT NOT NULL DEFAULT '', stage TEXT NOT NULL DEFAULT 'qualify', created_at TEXT NOT NULL, UNIQUE(owner,email));
CREATE TABLE lead_stages (id INTEGER PRIMARY KEY, lead_id INTEGER NOT NULL REFERENCES leads(id), stage TEXT NOT NULL, note TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE lead_touches (id INTEGER PRIMARY KEY, lead_id INTEGER NOT NULL REFERENCES leads(id), note TEXT NOT NULL, at TEXT NOT NULL, queue_id INTEGER REFERENCES queue_items(id));
